float outline(vec2 uv, vec2 lo, vec2 hi, float w) {
    vec2 px = w / iResolution.xy;
    vec2 a = step(lo - px, uv) * step(uv, hi + px);
    vec2 b = step(lo + px, uv) * step(uv, hi - px);
    return a.x * a.y - b.x * b.y;
}
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;
    vec3 src = texture(iChannel0, uv).rgb;
    float l = dot(src, vec3(0.2126, 0.7152, 0.0722));
    vec3 col = vec3(smoothstep(0.3, 0.7, l)) * 0.9;
    // Nothing tracked reads as zero size; most of the frame at once is a
    // lighting change, not a subject. Either way the overlay goes.
    float area = U.p2.x * U.p3.x;
    float on = step(0.00005, area) * step(area, 0.5);
    vec2 ctr = vec2(U.p0.x, 1.0 - U.p1.x);
    vec2 hs = max(vec2(U.p2.x, U.p3.x) * 0.5 + 0.015, vec2(0.03));
    vec2 px = 1.0 / iResolution.xy;
    float box = outline(uv, ctr - hs, ctr + hs, 1.5);
    float inner = outline(uv, ctr - hs * 0.2, ctr + hs * 0.2, 1.0);
    vec2 d = abs(uv - ctr);
    float hair = (step(d.x, px.x) * step(hs.y, d.y) + step(d.y, px.y) * step(hs.x, d.x)) * 0.85;
    vec2 g = fract(uv * vec2(32.0, 18.0));
    float grid = step(g.x, 0.04) * step(g.y, 0.07) * 0.18;
    float scan = 0.92 + 0.08 * sin(fragCoord.y * 1.7);
    vec3 hud = vec3(1.0, 0.18, 0.12);
    col = mix(col * scan + grid, hud, clamp((box + inner + hair) * on, 0.0, 1.0));
    fragColor = vec4(col, 1.0);
}
